		if (formOpen && agentOptions.length > 0) {
            if (!prefill_assignee) {
                if (userMode === "agent" && !user.account.isservicemanager) {
                    const currentAgent = agentOptions.find((agent) => agent.value === userId);
                    if (currentAgent) {
                        setFormData((prev) => ({ ...prev, staff_assigned: currentAgent.value }));
                    }
                }
            }
		}
	}, [formOpen, agentOptions]);

	useEffect(() => {
		if (formOpen && serviceManagerOptions.length > 0) {
			if (userMode === "agent" && (user.account.isservicemanager || user.account.isadmin)) {
				const currentAgent = serviceManagerOptions.find((agent) => agent.value === userId);
				if (currentAgent) {
					setFormData((prev) => {
						// Only set if staff_accountable is NOT already set
						if (!prev.staff_accountable) {
							return { ...prev, staff_accountable: currentAgent.value };
						}
						return prev;
					});
				}
			}
		}
	}, [formOpen, serviceManagerOptions]);

	useEffect(() => {
		// Keep selected checklist in sync with available forms
		if (customFormsForServiceType.length > 0) {
			const exists = customFormsForServiceType.some((f) => String(f.id) === String(selectedChecklistId));
			if (!exists) {
				const defaults = customFormsForServiceType.filter((f) => f.isDefault === true);
				const getRank = (f) => {
					const r = Number(f?.match_rank);
					return Number.isFinite(r) ? r : Number.MAX_SAFE_INTEGER;
				};
				const bestDefault = defaults.length > 0
					? defaults.reduce((best, cur) => (getRank(cur) < getRank(best) ? cur : best), defaults[0])
					: null;
				const nextId = bestDefault?.id || customFormsForServiceType[0].id;
				if (String(selectedChecklistId) !== String(nextId)) {
					setSelectedChecklistId(nextId);
				}
			}
		} else {
			if (selectedChecklistId !== null) setSelectedChecklistId(null);
		}
	}, [customFormsForServiceType]);

	const handleEditorChange = ({ html, text, json }) => {
		setFormData((prev) => ({ ...prev, description: html }));
		if (formErrors.description) {
			setFormErrors((prev) => ({ ...prev, description: false }));
		}
	};

	const handleDateChange = (name) => (newValue) => {
		handleFormChange({ target: { name, value: moment(newValue) } });
	};

	const handleFormChange = (e) => {
		const { name, value } = e.target;
		setFormData((prevData) => ({
			...prevData,
			[name]: value,
		}));
	};

	const handleCloseForm = () => {
		const hasChanged = !_.isEqual(formData, initialFormDataRef.current);

		if (!hasChanged) {
			setFormOpen(false);
			setFormData({
				customer: null,
				user: null,
				equipment: null,
				subject: "",
				description: "",
				ticket_notice: "all",
				priority: defaultPriority ? getPriorityValue(defaultPriority) : 2,
				attachment: null,
				files: [],
				staff_accountable: null,
				staff_assigned: null,
				sla: "",
				ticket_source: "web",
				department: null,
				service_type: defaultServiceTypeId || serviceTypes?.[0]?.value || null,
				due_date: null,
				email_id: null,
			});
			return;
		}
		AlertService.confirmDiscard().then((result) => {
			if (result.isConfirmed) {
				setFormOpen(false);
				setFormData({
					customer: null,
					user: null,
					equipment: null,
					subject: "",
					description: "",
					ticket_notice: "all",
					priority: defaultPriority ? getPriorityValue(defaultPriority) : 2,
					attachment: null,
					files: [],
					staff_accountable: null,
					staff_assigned: null,
					sla: "",
					ticket_source: "web",
					department: null,
					service_type: defaultServiceTypeId || serviceTypes?.[0]?.value || null,
					due_date: null,
					email_id: null,
				});
			}
		});
	};

	const validateMainStep = () => {
		// Build required fields based on user type
		let requiredFields = [
			"customer",
			"user",
			"subject",
			"priority",
			"service_type",
		];

		// Only require department and due_date for agents
		if (isAgent) {
			requiredFields.push("department");
			requiredFields.push("due_date");
		}

		const errors = {};

		requiredFields.forEach((field) => {
			const value = formData[field];

			// Special handling for subject field
			if (field === "subject") {
				// Trim the subject and check if empty
				const trimmedSubject = value ? value.trim() : "";
				if (trimmedSubject === "") {
					errors[field] = true;
				} else if (trimmedSubject.length > 175) {
					errors[field] = "Subject must be 175 characters or less";
				}
			} else {
				// Check for null, empty string, or invalid moment date for other fields
				if (value === null || value === "" || (moment.isMoment(value) && !value.isValid())) {
					errors[field] = true;
				}
			}
		});

		if (Object.keys(errors).length > 0) {
			setFormErrors(errors);
			// Check if there's a specific error message for subject field
			if (errors.subject && typeof errors.subject === 'string') {
				setAlert(errors.subject);
			} else {
				setAlert("Please fill all the required fields.");
			}
			return false;
		}
		setFormErrors({});
		setAlert(null);
		return true;
	};

    const validateCustomForms = () => {
        // Validate only the currently selected form (stepper renders one at a time)
        const selectedForm = customFormsForServiceType.find((f) => String(f.id) === String(selectedChecklistId)) || customFormsForServiceType[0];
        if (!selectedForm) {
            setCustomFormErrors({});
            return true;
        }
        const validationErrors = validateCustomFormsShared([selectedForm], customFormValues, { userMode });
        setCustomFormErrors(validationErrors);
        if (Object.keys(validationErrors).length > 0) {
            // Do not set global alert here; we'll render field-level list above the form
            return false;
        }
        // Clear any previous alert when validation passes
        setAlert(null);
        return true;
    };

	const handleCustomFieldChange = (fieldId, value) => {
		setCustomFormValues((prev) => ({ ...prev, [fieldId]: value }));
	};

	const handleNext = () => {
		if (!useStepper) return;
		if (activeStep === 0) {
			if (!validateMainStep()) return;
		}
		if (activeStep === 1) {
			if (!validateCustomForms()) return;
		}
		setActiveStep((prev) => Math.min(prev + 1, 1));
	};
 	const handleBack = () => {
 		if (!useStepper) return;
 		setActiveStep((prev) => Math.max(prev - 1, 0));
 	};

 	const handleSubmit = async () => {
		if (formSubmitting) return;
 		const entityKey = "ticket";
 		const action = "create";
 		const entityLabel = getNamespace(entityKey, { capitalize: true, plural: false });
 		if (useStepper) {
 			if (activeStep === 0) {
				if (!validateMainStep()) return;
				setActiveStep(1);
				return;
			}
			if (!validateCustomForms()) return;
		} else {
			if (!validateMainStep()) return;
		}
 		console.log("Submitting: ", formData);
 		// No errors
 		setFormErrors({});
 		setAlert(null); // clear previous alerts if any
		setFormSubmitting(true);

 		// Prepare trimmed data for API submission
 		const trimmedFormData = { ...formData };
 		//Exclude department for non-agents
 		if (!isAgent) {
            delete trimmedFormData.department;
        }

		// Trim subject field
		if (trimmedFormData.subject) {
			trimmedFormData.subject = trimmedFormData.subject.trim();
		}

		// For description (RichTextEditor), we keep the HTML but ensure it's properly formatted
		// The validation already ensures there's meaningful content, so we just clean up any extra whitespace
		if (trimmedFormData.description) {
			// Remove leading/trailing whitespace from HTML content
			trimmedFormData.description = trimmedFormData.description.trim();
		}

		const fd = new FormData();
		Object.entries(trimmedFormData).forEach(([key, value]) => {
			if (key !== "files" && key !== "email_id") {
				fd.append(key, value ?? "");
			}
		});
		// Append email_id from ref — bypasses React state batching race conditions
		if (emailIdRef.current) {
			fd.append("email_id", emailIdRef.current);
		}
		if (formData.files) {
			formData.files.forEach((file) => {
				fd.append("files", file, file.name);
			});
		}
		if (useStepper && customFormsForServiceType.length > 0) {
			const selectedForm = customFormsForServiceType.find((f) => String(f.id) === String(selectedChecklistId)) || customFormsForServiceType[0];
			const fieldsSource = selectedForm?.fields || selectedForm?.schema?.fields || [];
			const fieldsWithValue = fieldsSource.map((field) => {
				const rawVal = (customFormValues && customFormValues[field.name] !== undefined)
					? customFormValues[field.name]
					: (field.value !== undefined ? field.value : "");
				if (field.type === 'attachment') {
					const attType = rawVal?.attachmentType || 'na';
					let fileName = null;
					if (attType === 'custom_form_files') {
						const f = rawVal?.file;
						if (Array.isArray(f) && f.length > 0) {
							const first = f[0];
							fileName = typeof first === 'string' ? first : (first?.name || first?.filename || null);
						} else if (f && typeof f === 'object') {
							fileName = f.name || f.filename || null;
						} else if (typeof f === 'string') {
							fileName = f;
						}
					}
					return {
						...field,
						value: {
							attachmentType: attType === 'custom_form_files' ? 'custom_form_files' : (attType === 'url' ? 'url' : 'na'),
							attachmentUrl: attType === 'url' ? (rawVal?.attachmentUrl || null) : null,
							file: attType === 'custom_form_files' ? fileName : null,
							rel: field.name,
						},
					};
				}
				if (field.type === 'file_upload') {
					const v = rawVal;
					let fileName = null;
					if (Array.isArray(v) && v.length > 0) {
						const first = v[0];
						fileName = typeof first === 'string' ? first : (first?.name || first?.filename || null);
					} else if (v && typeof v === 'object') {
						fileName = v.name || v.filename || null;
					} else if (typeof v === 'string') {
						fileName = v;
					}
					return {
						...field,
						value: {
							attachmentType: 'custom_form_files',
							file: fileName,
							rel: field.name,
						},
					};
				}
				if (field.type === 'inspection') {
					const v = rawVal || {};
					const filesRaw = v.files || v.file || [];
					let fileNames = [];
					if (Array.isArray(filesRaw)) {
						fileNames = filesRaw.map((f) => {
							if (!f) return null;
							if (typeof f === 'string') return f;
							if (typeof f === 'object') return f.name || f.filename || null;
							return null;
						}).filter(Boolean);
					} else if (filesRaw && typeof filesRaw === 'object') {
						const name = filesRaw.name || filesRaw.filename || null;
						if (name) fileNames = [name];
					}
					return {
						...field,
						value: {
							inspection: v.inspection ?? null,
							notes: v.notes || null,
							files: fileNames,
						},
					};
				}
				return {
					...field,
					value: rawVal,
				};
			});

			// Collect and append actual files from custom form fields to FormData as 'custom_form_files'
			const appendCustomFormFiles = (field, rawVal) => {
				const tryAppendFile = (file) => {
					if (!file) return;
					const isFileObject = (typeof File !== 'undefined' && file instanceof File) || (file && typeof file === 'object' && 'name' in file && 'size' in file);
					if (isFileObject) {
						fd.append('custom_form_files', file, file.name);
					}
				};
				if (!rawVal) return;
				if (field.type === 'attachment') {
					if (rawVal.attachmentType === 'custom_form_files') {
						// rawVal.file can be a single File or array
						if (Array.isArray(rawVal.file)) {
							rawVal.file.forEach(tryAppendFile);
						} else {
							tryAppendFile(rawVal.file);
						}
					}
				} else if (field.type === 'file_upload') {
					const v = rawVal;
					if (Array.isArray(v)) {
						v.forEach(tryAppendFile);
					} else {
						tryAppendFile(v);
					}
				} else if (field.type === 'inspection') {
					const files = rawVal?.files || rawVal?.file;
					if (Array.isArray(files)) {
						files.forEach(tryAppendFile);
					} else {
						tryAppendFile(files);
					}
				}
			};

			fieldsSource.forEach((field) => {
				if (['attachment', 'file_upload', 'inspection'].includes(field?.type)) {
					const rawVal = customFormValues[field.name];
					appendCustomFormFiles(field, rawVal);
				}
			});

			const customFormDataPayload = [
				{
					form_id: selectedForm?.id,
					form_version: selectedForm?.latestVersion,
					form_value: {
						title: selectedForm?.title || `Form #${selectedForm?.id}`,
						fields: fieldsWithValue,
					},
				},
			];
			console.log("Custom Form Data Payload (final): ", customFormDataPayload);
			fd.append("custom_form_data", JSON.stringify(customFormDataPayload));
		}

 		try {
 		const response = await createTicketsService(fd);
 		if (response.status) {
			// if (fetchParentData) {
			// 	await fetchParentData();
			// }
			if (updateTickets) updateTickets();
			if (setParentData) setParentData();

				// Success Alert (USING ALERT SERVICE - createSuccess Toast)
				AlertService.createSuccess(
					entityLabel,
					`The ${entityLabel} has been created successfully`
				);

				// Reset form data (keeping original logic)
			setFormData({
				customer: null,
				user: null,
				equipment: null,
				subject: "",
				description: "",
				ticket_notice: "all",
				priority: defaultPriority ? getPriorityValue(defaultPriority) : 2,
				attachment: null,
				files: [],
				staff_accountable: null,
				staff_assigned: null,
				sla: "",
				ticket_source: "web",
				department: null,
				service_type: defaultServiceTypeId || serviceTypes?.[0]?.value || null,
				due_date: null,
				email_id: null,
			});
			setTimeout(() => {
				setFormSubmitting(false);
				setFormOpen(false);

				navigate(`/${nsp("ticket")}/${response.data.ticket_id}`);
			}, 1500);
		} else {
			// API Failure (Logic Failure Toast)
			setFormLoading(false);
			setFormSubmitting(false);

				AlertService.logicFailure(
					action,
					entityLabel,
					response.message || `Failed to create ${entityLabel.toLowerCase()}. Please check your input.`
				);
				setAlert(response.message); // Keep local alert for display near form fields if needed
			}
		} catch (error) {
			// System/Network Error (System Error Toast)
			setFormLoading(false);
			setFormSubmitting(false);

			AlertService.systemError(
				error.message || `Failed to ${action} ${entityLabel.toLowerCase()}. Network error.`
			);
			setAlert(error.message); // Keep local alert for display near form fields if needed
		}
	};

	const renderCustomFormsStep = () => {
		if (customFormsForServiceType.length === 0) return null;
		const selectedForm = customFormsForServiceType.find((f) => String(f.id) === String(selectedChecklistId)) || customFormsForServiceType[0];
		return (
			<Box>
			{/* Show custom form validation errors above the form like TicketContent */}
			{Object.keys(customFormErrors || {}).length > 0 && (
				<Box sx={{ mb: 1 }}>
					{Object.entries(customFormErrors).map(([fieldKey, fieldErr]) => {
						const label = getFieldLabelByKeyCF(selectedForm, fieldKey);
						if (typeof fieldErr === 'string') {
							return (
								<Alert key={fieldKey} severity="error" sx={{ width: "100%", mb: 1 }}>
									{label}: {fieldErr}
								</Alert>
							);
						}
						return (
							<Box key={fieldKey}>
								{fieldErr?.notes && (
									<Alert severity="error" sx={{ width: "100%", mb: 1 }}>
										{label}: {fieldErr.notes}
									</Alert>
								)}
								{fieldErr?.files && (
									<Alert severity="error" sx={{ width: "100%", mb: 1 }}>
										{label}: {fieldErr.files}
									</Alert>
								)}
							</Box>
						);
					})}
				</Box>
			)}
				<FormField
					type="autocomplete"
					label={getNamespace("custom_form", { capitalize: true, plural: false })}
					name="selected_checklist"
					value={selectedChecklistId || selectedForm?.id || null}
					onChange={(e) => setSelectedChecklistId(e.target.value)}
					options={customFormsForServiceType.map((f) => ({ label: f.name || `Form #${f.id}`, value: f.id }))}
					showRequired={false}
					disabled={userMode === "user"}  // disable for customer user login
					/>
				<Box sx={{ mt: 2 }}>
					<CustomFormDetail
						open={false}
						setOpen={() => {}}
						form_data={selectedForm}
						setSelectedFormDetail={() => {}}
						loading={false}
						onValuesChange={(vals) => setCustomFormValues(vals)}
						mode="embed"
                        validationErrors={customFormErrors}
					/>
				</Box>
			</Box>
		);
	};

	const formButtons = useStepper
		? (activeStep === 0
				? [
					{
						label: "Next",
						icon: null,
						onClick: () => {
							handleNext();
						},
						variant: "contained",
					},
				]
				: [
					{
						label: `Back`,
						icon: null,
						onClick: () => {
							handleBack();
						},
						variant: "contained",
					},
					{
						label: activeStep === 1 ? `Submit` : "Next",
						icon: null,
						onClick: () => {
							if (activeStep === 1) {
								handleSubmit();
							} else {
								handleNext();
							}
						},
						variant: "contained",
					},
				])
		: [
			{
				label: `Submit`,
				icon: null,
				onClick: () => {
					handleSubmit();
				},
				variant: "contained",
			},
		];

	return (
		<>
			<LocalizationProvider dateAdapter={AdapterMoment}>
				<DrawerForm
					open={formOpen}
					setOpen={setFormOpen}
					handleClose={handleCloseForm}
					handleSubmit={handleSubmit}
					formButtons={formButtons}
					alert={alert}
					isExpanded={isExpanded}
					setIsExpanded={setIsExpanded}
					isExpandedToggle={false}
					formTitle={formTitle.title}
					formSubTitle={formTitle.subtitle}>
					{formSubmitting || formLoading ? (
						<Box
							p={2}
							width="100%"
							sx={{
								...flexCol,
								justifyContent: "center",
								alignItems: "center",
								minHeight: "500px",
							}}>
							<CircularProgress />
							{formSubmitting && (
								<Typography variant="h6" mt={2}>
									Creating New{" "}
									{getNamespace("ticket", {
										capitalize: true,
										plural: false,
									})}
								</Typography>
							)}
						</Box>
					) : (
						<>
							{useStepper && (
								<Stepper activeStep={activeStep} alternativeLabel>
									{[
										{
											label: `${getNamespace("ticket", { capitalize: true, plural: false })} Details`,
											description: `Provide ${getNamespace("organization", { plural: false })}, ${getNamespace("organization_user", {
												plural: false,
											})}, ${getNamespace("provision_equipment", {
												plural: false,
											})}, ${getNamespace("service_type", {
												plural: false,
											})}, priority and describe the issue.`,
										},
										{
											label: `${getNamespace("custom_form", { capitalize: true, plural: false })}`,
											description: `Complete the ${getNamespace("custom_form", { capitalize: true, plural: false })} required for the selected ${getNamespace("service_type", {
												plural: false,
											})} and ${getNamespace("provision_equipment", {
												plural: false,
											})}.`
										},  
									].map((step) => (
										<Step key={step.label}>
											<StepLabel>
												<Typography variant="body1" fontWeight={"bold"}>{step.label}</Typography>
												<Typography variant="body2" fontSize={"11px"} color="text.secondary">{step.description}</Typography>
											</StepLabel>
										</Step>
									))}
								</Stepper>
							)}
							{!useStepper || activeStep === 0 ? (
								<>
							{isAgent && (
								<>
									<FormField
										type="autocomplete"
										label={getNamespace("organization", { capitalize: true, plural: false })}
										name="customer"
										value={formData.customer}
										error={formErrors.customer}
										onChange={handleFormChange}
										options={customerOptions}
										showRequired={true}
										inputRef={textFieldRef}
									/>

									<FormField
										type="groupedByCustomer-UserDropdown"
										label={getNamespace("organization_user", { capitalize: true, plural: false })}
										name="user"
										value={formData.user}
										error={formErrors.user}
										onChange={handleFormChange}
										options={userOptions}
										showRequired={true}
									/>
								</>
							)}
							<FormField
								type="autocomplete"
								label={getNamespace("provision_equipment", { capitalize: true, plural: false })}
								name="equipment"
								value={formData.equipment}
								error={formErrors.equipment}
								onChange={handleFormChange}
								options={equipmentOptions}
								showRequired={false}
							/>			
						 	<Divider flexItem />
							<FormField
								type="select"
								label="Service Type"
								name="service_type"
								value={formData.service_type}
								error={formErrors.service_type}
								onChange={handleFormChange}
								options={serviceTypes}
								showRequired={true}
							/>
							{routingTagInfo && (
								<Box width="100%" display="flex" mt={0.5}>
									<Typography variant="body2" color="text.secondary" fontSize="11px">
										{isAgent ? (
											<>
												Routing tag applied: <b>{routingTagInfo.name}</b>. Service types and departments are filtered by this tag.
											</>
										) : (
											<>
												Available service types have been updated for the selected {getNamespace("provision_equipment", { capitalize: false, plural: false })}.
											</>
										)}
									</Typography>
								</Box>
							)}
							{isAgent && (
								<>				
							<FormField
								type="select"
								label="Department"
								name="department"
								value={formData.department}
								error={formErrors.department}
								onChange={handleFormChange}
								options={isAgent ? departmentsOptionsFiltered : departmentsOptions}
								showRequired={true}
							/>
								{isAgent && departmentsOptionsFiltered.length === 0 && (
									<Box width="100%" display="flex" mt={0.5}>
										<Typography variant="body2" color="error" fontSize="11px">
											<b>Note:</b> No departments available for the selected service type. Please contact your administrator.
										</Typography>
									</Box>
								)}
									{/* <Divider flexItem /> */}
									<FormField
										type="userDropdown"
										label="Accountable"
										name="staff_accountable"
										value={formData.staff_accountable}
										error={formErrors.staff_accountable}
										onChange={handleFormChange}
										options={serviceManagerOptions}
										showRequired={false}
									/>

