const moment = require("moment-timezone");
const { Op } = require("sequelize");
const db = require("../models");
const { models, sequelize } = db;
const { parseTimeToMinutes } = require("./billingTimeUtils");

const DEFAULT_FALLBACK_DAYS = 7;
const DAY_KEYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];

const normalizeTimezone = (timezone) => {
	if (!timezone) return null;
	return moment.tz.zone(timezone) ? timezone : null;
};

const buildSegmentsByDay = (windows = []) => {
	const segmentsByDay = Object.fromEntries(DAY_KEYS.map((day) => [day, []]));
	for (const window of windows) {
		let dayKey = (window.day_of_week || "").toLowerCase().trim();
		if (!dayKey) continue;

		// Map full names to 3-letter keys if necessary
		if (dayKey.startsWith("sun")) dayKey = "sun";
		else if (dayKey.startsWith("mon")) dayKey = "mon";
		else if (dayKey.startsWith("tue")) dayKey = "tue";
		else if (dayKey.startsWith("wed")) dayKey = "wed";
		else if (dayKey.startsWith("thu")) dayKey = "thu";
		else if (dayKey.startsWith("fri")) dayKey = "fri";
		else if (dayKey.startsWith("sat")) dayKey = "sat";

		if (!DAY_KEYS.includes(dayKey)) continue;
		const startMin = parseTimeToMinutes(window.start_time);
		const endMin = parseTimeToMinutes(window.end_time);
		if (startMin === null || endMin === null || startMin === endMin) continue;
		if (endMin < startMin) {
			segmentsByDay[dayKey].push({ startMin, endMin: 1440 });
			const nextDayIdx = (DAY_KEYS.indexOf(dayKey) + 1) % DAY_KEYS.length;
			const nextDay = DAY_KEYS[nextDayIdx];
			segmentsByDay[nextDay].push({ startMin: 0, endMin });
		} else {
			segmentsByDay[dayKey].push({ startMin, endMin });
		}
	}
	for (const key of DAY_KEYS) {
		segmentsByDay[key].sort((a, b) => a.startMin - b.startMin);
	}
	return segmentsByDay;
};

const resolveHolidayList = async ({ ticketId, equipmentId, userId, timeRules, transaction }) => {
	let country = "";
	if (equipmentId) {
		const equipment = await models.organization_equipments.findOne({
			where: { id: equipmentId },
			include: [{ model: models.organization_sites }],
			transaction,
		});
		country =
			equipment?.organization_site?.country ||
			equipment?.organization_sites?.country ||
			"";
	}
	if (!country && ticketId) {
		const ticket = await models.ticket.findOne({
			where: { ticket_id: ticketId },
			include: [
				{
					model: models.organization_equipments,
					as: "ticket_equipment",
					include: [{ model: models.organization_sites }],
				},
			],
			transaction,
		});
		country =
			ticket?.ticket_equipment?.organization_site?.country ||
			ticket?.ticket_equipment?.organization_sites?.country ||
			"";
	}

	const normalized = (country || "").trim().toLowerCase();
	if (normalized) {
		const list = await models.holiday_lists.findOne({
			where: sequelize.where(
				sequelize.fn("lower", sequelize.col("applicable_country")),
				normalized
			),
			include: [{ model: models.holidays, as: "holidays" }],
			transaction,
		});
		if (list) return list;
	}

	if (timeRules?.holiday_list_id) {
		const list = await models.holiday_lists.findByPk(timeRules.holiday_list_id, {
			include: [{ model: models.holidays, as: "holidays" }],
			transaction,
		});
		if (list) return list;
	}

	const fallback = await models.holiday_lists.findOne({
		where: {
			[Op.or]: [{ applicable_country: null }, { applicable_country: "" }],
		},
		include: [{ model: models.holidays, as: "holidays" }],
		transaction,
	});
	return fallback;
};

const computeDueDateFromSchedule = ({
	startDate,
	minutesToAdd,
	timeRules,
	holidayDates,
	fallbackTimezone = "UTC",
	timezoneOverride = null,
}) => {
	if (!timeRules?.windows?.length || minutesToAdd <= 0) {
		return null;
	}
	const timezone =
		normalizeTimezone(timezoneOverride) ||
		normalizeTimezone(timeRules.timezone) ||
		normalizeTimezone(fallbackTimezone) ||
		"UTC";
	const segmentsByDay = buildSegmentsByDay(timeRules.windows);
	const hasSegments = DAY_KEYS.some((day) => segmentsByDay[day]?.length);
	if (!hasSegments) return null;

	// Normalise holidays to YYYY-MM-DD strings in the schedule's timezone
	const holidaySet = new Set();
	if (Array.isArray(holidayDates)) {
		for (const hDate of holidayDates) {
			if (!hDate) continue;
			// Normalise hDate (could be Moment, Date or String)
			const formatted = moment.tz(hDate, timezone).format("YYYY-MM-DD");
			holidaySet.add(formatted);
		}
	}

	let current = startDate ? moment.tz(startDate, timezone) : moment.tz(timezone);
	current = current.seconds(0).milliseconds(0);

	let remaining = minutesToAdd;
	let holidaysExcludedCount = 0;
	let guard = 0; // Prevent infinite loops

	while (remaining > 0 && guard < 3660) {
		guard += 1;
		const dayKey = DAY_KEYS[current.day()];
		const currentDateKey = current.format("YYYY-MM-DD");

		// If today is a holiday, skip the whole day
		if (holidaySet.has(currentDateKey)) {
			holidaysExcludedCount += 1;
			current = current.clone().add(1, "day").startOf("day");
			continue;
		}

		const segments = segmentsByDay[dayKey] || [];
		if (!segments.length) {
			current = current.clone().add(1, "day").startOf("day");
			continue;
		}

		let currentMinutes = current.hours() * 60 + current.minutes();
		let consumedTimeOnThisDay = false;

		for (const segment of segments) {
			if (segment.endMin <= currentMinutes) continue;
			const startMin = Math.max(segment.startMin, currentMinutes);
			const availableInThisSegment = segment.endMin - startMin;
			if (availableInThisSegment <= 0) continue;

			if (remaining <= availableInThisSegment) {
				const finalMoment = current
					.clone()
					.startOf("day")
					.add(startMin + remaining, "minutes");

				return {
					dueDate: finalMoment,
					holidaysExcluded: holidaysExcludedCount
				};
			}

			remaining -= availableInThisSegment;
			currentMinutes = segment.endMin;
			consumedTimeOnThisDay = true;
		}

		current = current.clone().add(1, "day").startOf("day");
	}

	return null;
};

// SLA resolution precedence:
// 1) Explicit SLA
// 2) Customer tier rules (service type + priority, then service type only, then priority only)
// 3) Customer tier default SLA
// 4) Department SLA
const resolveSlaForTicket = async ({
	slaId,
	deptId,
	userId,
	customerId,
	priorityId,
	serviceTypeId,
	transaction,
}) => {
	if (slaId) {
		const sla = await models.sla.findByPk(slaId, { transaction });
		if (sla) return sla;
	}

	let orgId = customerId || null;
	if (!orgId && userId) {
		const user = await models.user.findByPk(userId, { attributes: ["org_id"], transaction });
		orgId = user?.org_id || null;
	}

	const normalizedPriorityId = priorityId ? Number(priorityId) : null;
	const normalizedServiceTypeId = serviceTypeId ? Number(serviceTypeId) : null;

	if (orgId) {
		const org = await models.organization.findByPk(orgId, { attributes: ["customer_tier_id"], transaction });
		if (org?.customer_tier_id) {
			if (normalizedServiceTypeId && normalizedPriorityId) {
				const rule = await models.customer_tier_sla_rules.findOne({
					where: {
						customer_tier_id: org.customer_tier_id,
						service_type_id: normalizedServiceTypeId,
						priority_id: normalizedPriorityId,
					},
					include: [{ model: models.sla, as: "sla" }],
					transaction,
				});
				if (rule?.sla) return rule.sla;
			}
			if (normalizedServiceTypeId) {
				const rule = await models.customer_tier_sla_rules.findOne({
					where: {
						customer_tier_id: org.customer_tier_id,
						service_type_id: normalizedServiceTypeId,
						priority_id: { [Op.is]: null },
					},
					include: [{ model: models.sla, as: "sla" }],
					transaction,
				});
				if (rule?.sla) return rule.sla;
			}
			if (normalizedPriorityId) {
				const rule = await models.customer_tier_sla_rules.findOne({
					where: {
						customer_tier_id: org.customer_tier_id,
						priority_id: normalizedPriorityId,
						service_type_id: { [Op.is]: null },
					},
					include: [{ model: models.sla, as: "sla" }],
					transaction,
				});
				if (rule?.sla) return rule.sla;
			}

			const tier = await models.customer_tier.findByPk(org.customer_tier_id, {
				attributes: ["sla_id"],
				transaction,
			});
			if (tier?.sla_id) {
				const sla = await models.sla.findByPk(tier.sla_id, { transaction });
				if (sla) return sla;
			}
		}
	}

	if (deptId) {
		const dept = await models.department.findByPk(deptId, {
			include: [{ model: models.sla, as: "sla" }],
			transaction,
		});
		if (dept?.sla) return dept.sla;
	}

	return null;
};

const calculateTicketDueDate = async ({
	startDate,
	deptId,
	userId,
	customerId,
	equipmentId,
	slaId,
	priorityId,
	serviceTypeId,
	timezoneOverride,
	transaction,
}) => {
	const sla = await resolveSlaForTicket({
		slaId,
		deptId,
		userId,
		customerId,
		priorityId,
		serviceTypeId,
		transaction,
	});

	// Determine resolution source for debugging
	let resolutionSource = 'fallback';
	if (slaId) {
		resolutionSource = 'explicit_sla';
	} else if (sla && customerId) {
		// Check if it came from customer tier
		const org = await models.organization.findByPk(customerId, {
			attributes: ['customer_tier_id'],
			transaction
		});
		if (org?.customer_tier_id) {
			resolutionSource = 'customer_tier';
		}
	} else if (sla && deptId) {
		resolutionSource = 'department';
	}

	const effectiveTimezone = normalizeTimezone(timezoneOverride) || "UTC";

	if (!sla || !sla.schedule_id) {
		const fallback = startDate
			? moment.tz(startDate, effectiveTimezone).add(DEFAULT_FALLBACK_DAYS, "days")
			: moment.tz(effectiveTimezone).add(DEFAULT_FALLBACK_DAYS, "days");
		return {
			dueDate: fallback.utc().toDate(),
			slaId: sla?.id || null,
			sla: sla ? {
				id: sla.id,
				name: sla.name,
				grace_period: sla.grace_period,
				grace_unit: sla.grace_unit,
			} : null,
			resolutionSource: sla ? resolutionSource : 'fallback',
			usedFallback: true
		};
	}

	const timeRules = await models.time_rules.findByPk(sla.schedule_id, {
		include: [
			{ model: models.time_rule_windows, as: "windows" },
			{ model: models.holiday_lists, as: "holiday_list", include: [{ model: models.holidays, as: "holidays" }] },
		],
		transaction,
	});

	if (!timeRules?.windows?.length) {
		const fallback = startDate
			? moment.tz(startDate, effectiveTimezone).add(DEFAULT_FALLBACK_DAYS, "days")
			: moment.tz(effectiveTimezone).add(DEFAULT_FALLBACK_DAYS, "days");
		return {
			dueDate: fallback.utc().toDate(),
			slaId: sla.id,
			sla: {
				id: sla.id,
				name: sla.name,
				grace_period: sla.grace_period,
				grace_unit: sla.grace_unit,
			},
			resolutionSource,
			usedFallback: true,
			fallbackReason: 'no_time_rules'
		};
	}

	const holidayList = await resolveHolidayList({
		ticketId: null,
		equipmentId,
		userId,
		timeRules,
		transaction,
	});
	const holidayDates = (holidayList?.holidays || [])
		.map((holiday) => holiday.date)
		.filter(Boolean);

	const minutesToAdd = Math.ceil(
		moment.duration(sla.grace_period || 0, sla.grace_unit || "hours").asMinutes()
	);

	const computeResult = computeDueDateFromSchedule({
		startDate,
		minutesToAdd,
		timeRules,
		holidayDates,
		timezoneOverride: effectiveTimezone,
	});

	if (!computeResult) {
		const fallback = startDate
			? moment.tz(startDate, effectiveTimezone).add(DEFAULT_FALLBACK_DAYS, "days")
			: moment.tz(effectiveTimezone).add(DEFAULT_FALLBACK_DAYS, "days");
		return {
			dueDate: fallback.utc().toDate(),
			slaId: sla.id,
			sla: {
				id: sla.id,
				name: sla.name,
				grace_period: sla.grace_period,
				grace_unit: sla.grace_unit,
			},
			resolutionSource,
			usedFallback: true,
			fallbackReason: 'computation_failed'
		};
	}

	return {
		dueDate: computeResult.dueDate.utc().toDate(),
		slaId: sla.id,
		sla: {
			id: sla.id,
			name: sla.name,
			grace_period: sla.grace_period,
			grace_unit: sla.grace_unit,
			schedule_id: sla.schedule_id,
		},
		resolutionSource,
		usedFallback: false,
		holidaysExcluded: computeResult.holidaysExcluded
	};
};

module.exports = {
	calculateTicketDueDate,
	resolveSlaForTicket,
};

