const Sequelize = require("sequelize");
module.exports = (sequelize, DataTypes) => {
	return service_type.init(sequelize, DataTypes);
};

class service_type extends Sequelize.Model {
	static init(sequelize, DataTypes) {
		return super.init(
			{
				id: {
					autoIncrement: true,
					type: DataTypes.INTEGER,
					allowNull: false,
					primaryKey: true,
				},
				service_type: {
					type: DataTypes.STRING(255),
					allowNull: false,
				},
				notes: {
					type: DataTypes.TEXT,
					allowNull: true,
				},
				ispublic: {
					type: DataTypes.BOOLEAN,
					allowNull: false,
					defaultValue: true,
				},
				created_by: {
					type: DataTypes.INTEGER,
					allowNull: false,
				},
				updated_by: {
					type: DataTypes.INTEGER,
					allowNull: true,
				},
			},
			{
				sequelize,
				tableName: "service_type",
				timestamps: true,
				paranoid: true,
				indexes: [
					{
						name: "service_type_PRIMARY",
						unique: true,
						using: "BTREE",
						fields: [{ name: "id" }],
					},
				],
				hooks: {
					beforeDestroy: async (instance, options) => {
						// This runs before deletion attempt
						const { form_schema } = instance.sequelize.models;
						const dependentForms = await form_schema.count({
							where: { service_type_id: instance.id },
						});

						if (dependentForms > 0) {
							const err = new Error(
								`Cannot delete Service Type - ${dependentForms} form(s) depend on this service type`
							);
							err.name = "RestrictDeleteError";
							err.code = "RESTRICT_DELETE";
							err.status = 409;
							throw err;
						}
					},
				},
			}
		);
	}
}

